function calcularGeratriz(){const e=document.getElementById("input-decimal").value,t=document.getElementById("resultado-texto");if(!e||isNaN(e)){t.innerText="Insira um número válido.";return}const s=e.split(".");if(s.length===1){t.innerText=`${e}/1`;return}const r=s[1],n=10**r.length,o=Math.round(parseFloat(e)*n),i=(e,t)=>t===0?e:i(t,e%t),a=i(o,n);t.innerHTML=`<span class='frac'>${o/a}</span> / <span class='frac'>${n/a}</span>`}